const requested=new URLSearchParams(location.search).get('engine');const id=Object.hasOwn(configurations,requested)?requested:'rotary',cfg=configurations[id];
document.title=cfg.title.replace('.','')+' — Motion Lab';document.documentElement.style.setProperty('--blue',cfg.accent);$('engine-title').textContent=cfg.title;$('eyebrow').textContent=cfg.eyebrow+' / STUDY '+cfg.number;$('engine-subtitle').append(document.createTextNode(cfg.subtitle));const sub=document.createElement('span');sub.textContent=cfg.subline;$('engine-subtitle').appendChild(sub);$('model-tag').textContent=cfg.tag;$('angle').max=cfg.max;$('angle-label').textContent=cfg.angleLabel;$('angle-max').textContent='/ '+cfg.max+'°';$('energy-story').textContent=cfg.energy;$('look-closer').textContent=cfg.look;$('model-note').textContent=cfg.note;$('footer-label').textContent='MOTION LAB / ENGINE STUDY '+cfg.number;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,state={playing:!reduced&&!window.__studyHidden,power:45,cutaway:true,explode:false,orbit:false,selected:0};
let model;try{const module=await import('./engines/'+id+'.js');model=module.createModel();}catch(error){$('loading').textContent='The engine could not be loaded. Reload the page to try again.';document.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);console.error(error);throw error;}
const scene=new THREE.Scene();scene.background=new THREE.Color('#edf0f4');const camera=new THREE.PerspectiveCamera(34,1,.1,150);let renderer;try{renderer=new THREE.WebGLRenderer({antialias:true});}catch(error){$('loading').textContent='This study needs WebGL. Enable hardware acceleration or try another browser.';document.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);throw error;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.28;$('viewport').appendChild(renderer.domElement);$('loading').remove();
scene.add(new THREE.HemisphereLight(0xf1f7ff,0x626d7b,2.35));function light(color,intensity,p){const l=new THREE.DirectionalLight(color,intensity);l.position.set(...p);scene.add(l);return l;}const key=light(0xffffff,3.3,[5,10,7]);key.castShadow=true;key.shadow.mapSize.set(1024,1024);Object.assign(key.shadow.camera,{left:-9,right:9,top:9,bottom:-9});key.shadow.bias=-.0005;light(0xc7dfff,2.2,[-5,4,-6]);light(0xffffff,1.8,[0,3,-9]);
scene.add(model.root);model.root.traverse(o=>{if(o.isMesh){const mats=Array.isArray(o.material)?o.material:[o.material];o.castShadow=!mats.some(m=>m.transparent);o.receiveShadow=true;mats.forEach(m=>{if(m.transparent)m.depthWrite=false;});}});model.update(0,state);const bounds=new THREE.Box3().setFromObject(model.root),centre=bounds.getCenter(new THREE.Vector3());model.root.position.sub(centre);const size=bounds.getSize(new THREE.Vector3());const floor=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.ShadowMaterial({opacity:.15}));floor.rotation.x=-Math.PI/2;floor.position.y=bounds.min.y-centre.y-.06;floor.receiveShadow=true;scene.add(floor);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.075;controls.minDistance=2;controls.maxDistance=60;controls.maxPolarAngle=Math.PI*.94;controls.autoRotateSpeed=.6;
function fit(mode='three-quarter'){const poses={'three-quarter':model.camera??[7,5,9],front:[0,.02,1],side:[1,.08,0],top:[.01,1,.01]};const direction=new THREE.Vector3(...poses[mode]).normalize();const extent=Math.max(size.x,size.y,size.z,4)*(state.explode?1.4:1);const distance=extent/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*Math.max(1,1/camera.aspect)*1.13;controls.target.set(0,0,0);camera.position.copy(direction.multiplyScalar(distance));controls.update();$('camera').value=mode;}
function resize(){const r=$('viewport').getBoundingClientRect();if(r.width<1||r.height<1)return;camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height);fit($('camera').value);}new ResizeObserver(resize).observe($('viewport'));
function playing(on){state.playing=on;$('play').textContent=on?'Ⅱ Pause':'▶ Play';$('play').setAttribute('aria-label',on?'Pause animation':'Play animation');}
function power(value){state.power=Math.round(Math.min(100,Math.max(0,value)));$('power').value=state.power;$('power-value').textContent=state.power;}
function sync(){for(const k of ['explode','orbit'])$(k).checked=state[k];$('cutaway').classList.toggle('active',state.cutaway);$('complete').classList.toggle('active',!state.cutaway);$('cutaway').setAttribute('aria-pressed',String(state.cutaway));$('complete').setAttribute('aria-pressed',String(!state.cutaway));$('view-caption').textContent=cfg.title.replace('.','').toUpperCase()+' / '+(state.explode?'EXPLODED ASSEMBLY':state.cutaway?'CUTAWAY':'COMPLETE');controls.autoRotate=state.orbit;model.update(0,state);readout();}
function readout(){const r=model.getReadout();$('angle-value').textContent=Math.round(r.angle);$('angle').value=Math.min(cfg.max,Math.max(0,r.angle));$('phase-name').textContent=r.phase;$('phase-detail').textContent=r.detail;}
function select(part){if(!Number.isInteger(part)||part<0||part>=model.parts.length)throw Error('Unknown component');state.selected=part;const p=model.parts[part];$('part-counter').textContent=String(part+1).padStart(2,'0');$('part-total').textContent='/ '+String(model.parts.length).padStart(2,'0');$('part-title').textContent=p.name;$('part-category').textContent=p.category??cfg.tag;$('part-description').textContent=p.description;$('part-function').textContent=p.job;$('part-label').textContent=String(part+1).padStart(2,'0')+' — '+p.name;model.select(part);document.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle('active',+b.dataset.part===part);b.setAttribute('aria-pressed',String(+b.dataset.part===part));});}
model.parts.forEach((p,index)=>{const b=document.createElement('button');b.dataset.part=index;const n=document.createElement('span');n.textContent=String(index+1).padStart(2,'0');const title=document.createElement('strong');title.textContent=p.name;b.append(n,title);b.onclick=()=>select(index);$('stage-rail').appendChild(b);});
for(const legend of model.legend??(id==='steam'?[{label:'Admission',color:'#ff633e'},{label:'Exhaust',color:'#389eff'}]:id==='stirling'?[{label:'Hot region',color:'#e64b36'},{label:'Cold region',color:'#368abf'}]:[])){const span=document.createElement('span'),mark=document.createElement('i');mark.style.background=legend.color;span.append(mark,document.createTextNode(legend.label));$('view-legend').appendChild(span);}
const source=model.source??cfg.source??(id==='electric'?'https://www.ti.com/lit/pdf/sprabq3':id==='radial'?'https://www.faa.gov/sites/faa.gov/files/03_amtp_ch1.pdf':null);if(source){$('source-link').href=source;$('source-link').textContent='Learn more ↗';}else $('source-link').hidden=true;
$('play').onclick=()=>playing(!state.playing);$('power').oninput=e=>{power(+e.target.value);model.update(0,state);readout();};$('angle').oninput=e=>{playing(false);model.setAngle(+e.target.value);model.update(0,state);readout();};$('step').onclick=()=>{playing(false);model.setAngle((model.getReadout().angle+cfg.max/72)%cfg.max);model.update(0,state);readout();};$('cutaway').onclick=()=>{state.cutaway=true;sync();};$('complete').onclick=()=>{state.cutaway=false;sync();};for(const k of ['explode','orbit'])$(k).onchange=e=>{state[k]=e.target.checked;sync();if(k==='explode')fit($('camera').value);};$('camera').onchange=e=>fit(e.target.value);$('home').onclick=()=>fit();$('previous').onclick=()=>select((state.selected+model.parts.length-1)%model.parts.length);$('next').onclick=()=>select((state.selected+1)%model.parts.length);$('reset').onclick=()=>{Object.assign(state,{power:45,cutaway:true,explode:false,orbit:false});power(45);playing(!reduced);model.setAngle(0);select(0);sync();fit();};
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const candidates=model.pickables.filter(m=>{for(let p=m;p;p=p.parent)if(!p.visible)return false;return true;});const hit=ray.intersectObjects(candidates,false)[0];if(hit&&Number.isInteger(hit.object.userData.part))select(hit.object.userData.part);});
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON','SELECT','A'].includes(document.activeElement.tagName)){e.preventDefault();playing(!state.playing);}});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();playing(false);const notice=document.createElement('div');notice.id='loading';notice.textContent='Graphics paused. Reload the page to restore the study.';$('viewport').appendChild(notice);});
playing(state.playing);select(0);sync();resize();let previous=performance.now(),lastUI=0;function frame(now){if(window.__studyHidden){previous=now;requestAnimationFrame(frame);return;}const dt=Math.min(.05,(now-previous)/1000);previous=now;model.update(dt,state);if(now-lastUI>70){readout();lastUI=now;}controls.update();renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.studyControls={getState:()=>({...state,angle:model.getReadout().angle}),configure(input){if(!input||typeof input!=='object')throw Error('Expected settings');for(const key of Object.keys(input))if(!['power','playing','cutaway','explode','angle','component'].includes(key))throw Error('Unknown setting');for(const key of ['playing','cutaway','explode'])if(input[key]!==undefined&&typeof input[key]!=='boolean')throw Error('Expected boolean');if(input.power!==undefined&&(!Number.isFinite(input.power)||input.power<0||input.power>100))throw Error('Power must be 0–100');if(input.angle!==undefined&&(!Number.isFinite(input.angle)||input.angle<0||input.angle>cfg.max))throw Error('Angle out of range');if(input.component!==undefined&&(!Number.isInteger(input.component)||input.component<1||input.component>model.parts.length))throw Error('Component out of range');if(input.power!==undefined)power(input.power);if(input.playing!==undefined)playing(input.playing);if(input.angle!==undefined){playing(false);model.setAngle(input.angle);}for(const key of ['cutaway','explode'])if(input[key]!==undefined)state[key]=input[key];if(input.component!==undefined)select(input.component-1);sync();if(input.explode!==undefined)fit($('camera').value);return this.getState();}};
